from xml.etree import ElementTree as ET
path = r"C:\Github\ACIRV-Notebook\000-Arquivos-originais\AÇÕES COMUNICAÇÃO\09.11.26 Assembleia\Leads alvos.xlsx"
z = zipfile.ZipFile(path)
ns = {'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall('m:si', ns):
        shared.append(''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')))
sheet = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
rows=[]
for row in sheet.find('m:sheetData', ns).findall('m:row', ns):
    vals={}
    for c in row.findall('m:c', ns):
        ref=c.get('r'); col=re.match(r'([A-Z]+)',ref).group(1)
        t=c.get('t'); v=c.find('m:v',ns); isx=c.find('m:is',ns)
        if t=='s' and v is not None: val=shared[int(v.text)]
        elif t=='inlineStr' and isx is not None: val=''.join(x.text or '' for x in isx.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        else: val=v.text if v is not None else ''
        vals[col]=val
    rows.append(vals)
print(len(rows))
hdr=rows[1]
print({k:v for k,v in sorted(hdr.items())})
"}

